$ErrorActionPreference = 'Stop'
$projectRoot = Split-Path -Parent $PSScriptRoot
$path = Join-Path $projectRoot 'admin-panel\app\sahaba\page.tsx'
$source = [IO.File]::ReadAllText($path)
$start = $source.IndexOf('<label>Language <small>195 available</small>')
$end = $source.IndexOf('<style jsx>{`',$start)
if($start -lt 0 -or $end -lt 0){throw 'Sahaba replacement markers were not found.'}
$block = @'
<label>Language <small>195 available</small><button type="button" className="languagePicker" onClick={()=>setLanguageOpen(true)}><i>{form.languageCode.toUpperCase()}</i><span><b>{languages.find(item=>item.code===form.languageCode)?.label||form.language}</b><small>Select content language</small></span><strong>{"\u203A"}</strong></button></label><label>Sahabi / Sahabiyah name<input value={form.title} onChange={e=>setForm({...form,title:e.target.value})} required/></label><label>Writer / editor<input value={form.author} onChange={e=>setForm({...form,author:e.target.value})}/></label><label className="wide">Short description<textarea value={form.description} onChange={e=>setForm({...form,description:e.target.value})} required/></label><label className="wide cover"><span>Cover image</span><input type="file" accept="image/jpeg,image/png,image/webp" disabled={uploading} onChange={e=>{void upload(e.target.files?.[0]||null);e.currentTarget.value=""}}/>{form.coverImageUrl&&<div className="coverPreview"><img src={form.coverImageUrl} alt="Biography cover"/><div><b>Cover ready</b><button type="button" onClick={()=>setForm({...form,coverImageUrl:"",coverImageKey:""})}>Remove cover</button></div></div>}</label><div className="wide editor"><label>Biography pages</label><BookPageBuilder pages={form.pages||[]} content={form.content||""} api={API} token={tokenValue} language={form.language} recordId={`sahaba:${form.slug||"new"}:${form.languageCode}`} onMessage={setMessage} onChange={(pages,content)=>setForm({...form,pages,content})}/></div><label className="wide">Verified sources / references<input value={form.sourceUrl} onChange={e=>setForm({...form,sourceUrl:e.target.value})}/></label><label className="check"><input type="checkbox" checked={form.published} onChange={e=>setForm({...form,published:e.target.checked})}/> Publish in mobile app</label></div>{form.slug&&<button type="button" className="clear" onClick={()=>setForm(empty)}>Cancel editing</button>}</form><section className="panel library"><div className="libraryHead"><div><small>CONTENT LIBRARY</small><h2>Saved biographies</h2><p>{visible.length} of {items.length} biographies</p></div><div><input placeholder="Search name..." value={query} onChange={e=>setQuery(e.target.value)}/><select value={filter} onChange={e=>setFilter(e.target.value)}><option value="">All categories</option><option>Male Sahaba</option><option>Female Sahabiyat</option></select></div></div>{loading?<p className="empty">Loading biographies...</p>:visible.map(item=><article key={item.slug}><div className="thumb">{item.coverImageUrl?<img src={item.coverImageUrl} alt=""/>:<span>{item.title.slice(0,2)}</span>}</div><div><b>{item.title}</b><strong>{item.category}</strong><p>{item.description}</p><small>{item.language||"English"} - {item.published===false?"Draft":"Published"}</small></div><nav><button disabled={working===item.slug} onClick={()=>void edit(item)}>Edit</button><button className="delete" disabled={working===item.slug} onClick={()=>void remove(item)}>Remove</button></nav></article>)}{!loading&&!visible.length&&<p className="empty">No biography found.</p>}</section></section>{languageOpen&&<div className="languageModal" role="dialog" aria-modal="true" aria-label="Select Sahaba content language"><section><div className="languageModalHead"><div><small>SAHABA CONTENT</small><h2>Select Language</h2><p>{new Set(items.map(item=>item.languageCode||"en")).size} languages uploaded - 195 available</p></div><button type="button" onClick={()=>{setLanguageOpen(false);setLanguageSearch("")}}>{"\u00D7"}</button></div><label className="languageSearch"><span>{"\u2315"}</span><input autoFocus value={languageSearch} onChange={e=>setLanguageSearch(e.target.value)} placeholder="Search language or code..."/></label><div className="languageList">{languages.filter(item=>!languageSearch.trim()||`${item.label} ${item.code}`.toLowerCase().includes(languageSearch.trim().toLowerCase())).map(item=>{const count=items.filter(book=>(book.languageCode||"en")===item.code).length,selected=form.languageCode===item.code;return <button type="button" key={item.code} className={selected?"languageRow selected":"languageRow"} onClick={()=>{setForm({...form,languageCode:item.code,language:item.label});setLanguageOpen(false);setLanguageSearch("")}}><i>{item.code.slice(0,3).toUpperCase()}</i><span><b>{item.label}{item.code==="en"?" (Base)":""}</b><small>{count?`${count} ${count===1?"biography":"biographies"} uploaded`:"Not uploaded yet"}</small></span>{count>0?<em>{"\u2713"}</em>:<em className="emptyMark"/>}<strong>{"\u203A"}</strong></button>})}</div></section></div>}
'@
$source=$source.Substring(0,$start)+$block+$source.Substring($end)
[IO.File]::WriteAllText($path,$source,[Text.UTF8Encoding]::new($false))
